def triple_barrier_label(prices, upper_barrier, lower_barrier):
    for p in prices[1:]:
        if p >= upper_barrier:
            return 1
        if p <= lower_barrier:
            return -1
    return 0

triple_barrier_label([100, 101, 95, 106], 105, 96)

def calculate_average_uniqueness(concurrency_list):
    if not concurrency_list:
        return 0.0
    invs = [1.0 / c for c in concurrency_list]
    return sum(invs) / len(invs)

calculate_average_uniqueness([2, 4])

def is_event_overlapping(event_start, event_end, test_start, test_end):
    return not (event_end < test_start or event_start > test_end)

is_event_overlapping(1, 7, 6, 10)

def apply_embargo(test_end_idx, total_samples, embargo_pct=0.02):
    if total_samples <= 0:
        return 0
    embargo_len = int(total_samples * embargo_pct)
    return min(total_samples - 1, test_end_idx + embargo_len)

apply_embargo(100, 1000, 0.02)

def calculate_mda_scores(baseline_score, permuted_scores):
    return [round(baseline_score - s, 4) for s in permuted_scores]

calculate_mda_scores(0.85, [0.80, 0.85, 0.70])

def filter_features_by_mda(feature_names, mda_scores, threshold=0.01):
    return [name for name, score in zip(feature_names, mda_scores) if score >= threshold]

filter_features_by_mda(['f1', 'f2', 'f3'], [0.05, -0.01, 0.02], 0.01)
